  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const regions = []
  for (const c of all) {
    const r = regions[regions.length - 1]
    if (r && c.bs <= r.end) {
      r.end = Math.max(r.end, c.be)
      r.cs.push(c)
    } else regions.push({ start: c.bs, end: c.be, cs: [c] })
  }

  const out = []
  const info = []
  let pos = 0
  const stable = to => {
    if (to > pos) {
      const s = base.slice(pos, to)
      out.push({ lines: s })
      info.push(`stable ${s.length}`)
    }
  }
  const sideLines = (r, who, doc) => {
    const cs = r.cs.filter(c => c.who === who)
    if (!cs.length) return base.slice(r.start, r.end)
    const first = cs[0], last = cs[cs.length - 1]
