    const l = cs.reduce((a, c) => (c.be >= a.be ? c : a), last)
    const s = f.ss - (minBs - r.start)
    const e = l.se + (r.end - maxBe)
    return doc.slice(s, e)
  }
  for (const r of regions) {
    stable(r.start)
    const b = base.slice(r.start, r.end)
    const a = sideLines(r, 0, mine), t = sideLines(r, 1, theirs)
    if (same(a, t)) {
      out.push({ lines: a }); info.push(`both ${a.length}`)
    } else if (same(a, b)) {
      out.push({ lines: t }); info.push(`theirs ${t.length}`)
    } else if (same(t, b)) {
      out.push({ lines: a }); info.push(`mine ${a.length}`)
    } else {
      out.push({ conflict: true, a, b, t })
      info.push(`conflict mine=${a.length} base=${b.length} theirs=${t.length}`)
    }
    pos = r.end
  }
  stable(base.length)

  const conflict = out.some(o => o.conflict)
  let res = []
  if (mode === 'regions') res = info
  else {
    for (const o of out) {
      if (!o.conflict) res.push(...o.lines)
      else {
        res.push('<<<<<<< mine', ...o.a)
        if (mode === 'merge') res.push('||||||| base', ...o.b)
        res.push('=======', ...o.t, '>>>>>>> theirs')
      }
    }
  }
  if (res.length) process.stdout.write(res.join('\n') + '\n')
  process.exitCode = conflict ? 1 : 0
}
main()
